def main():
 pool={x['id']:x for f in ['master-candidates.json','study-candidates.json','lower-candidates.json'] for x in json.loads((BASE/f).read_text())['records']}
 excluded={x['id'] for x in json.loads((BASE/'editorial-exclusions.json').read_text())['records']}
 review={x['id']:x for f in ['master-review.json','study-review.json','deep-review.json','lower-review.json'] for x in json.loads((BASE/f).read_text())['records']}
 selected=[]
 for prefix,choices in [('draw-master-',CHOICES),('draw-study-',STUDIES)]:
  for suffix,level,aspect,solution in choices:
   ident=prefix+suffix;x=pool[ident];assert review[ident]['status']=='candidate'
   assert ident not in excluded, f'{ident} has a durable editorial exclusion'
   selected.append({**x,'level':level,'aspect':aspect,'solution':solution,'reviewStatus':'editorially-selected; bounded-engine-review','category':x.get('category','perpetual-check')})
 assert len({r['gameId'] for r in selected})==len(selected)
 (BASE/'selected-additions.json').write_text(json.dumps({'records':selected},ensure_ascii=False,indent=2)+'\n')
 print('Selected',len(selected),'additions; all remain unpublished pending integration and final checks.')
if __name__=='__main__':main()
